fn rm_of(name: &str) -> Option<RoundingMode> {
    match name {
        "ToEven" => Some(RoundingMode::ToEven),
        "Up" => Some(RoundingMode::Up),
        "None" => Some(RoundingMode::None),
        _ => None,
    }
}

#[test]
fn rem_pi_stress_is_correctly_rounded() -> Result<(), String> {
    let mut cc = Consts::new().map_err(|e| format!("{e:?}"))?;
    let mut bad = Vec::new();
    for &(xb, p, name, bits) in REF {
        let rm = rm_of(name).ok_or_else(|| format!("bad rm {name}"))?;
        let x = ExactNum::parse(xb, Radix::Bin, 1024, RoundingMode::None, &mut cc);
        let want = ExactNum::parse(bits, Radix::Bin, 512, RoundingMode::None, &mut cc);
        let got = x.rem_pi(p, rm, &mut cc);
        let cap = p.div_ceil(64).checked_mul(64).ok_or("cap overflow")?;
        let sig = got.mantissa_max_bit_len().ok_or("no mantissa")?;
        if got != want || sig > cap {
            bad.push(format!(
                "x=2^{} p={p} {name}: got {got:?} (mantissa {sig} bits), want {bits}",
                xb.len()
            ));
        }
    }
    if bad.is_empty() {
        Ok(())
    } else {
        Err(format!(
            "{} of {} rows differ:\n{}",
            bad.len(),
            REF.len(),
            bad.join("\n")
        ))
    }
}
